// Universal Input — standardizes input from WhatsApp or App Webhook
// Outputs: { message, sessionId, source, metadata } with structured metadata.user

let message = "";
let sessionId = "";
let metadata = {};
const item = items[0].json;

// 1. Source: WhatsApp (has contacts array)
if (item.contacts && item.contacts[0] && item.messages) {
  message = item.messages[0].text.body;
  sessionId = item.contacts[0].wa_id;
  metadata = item.metadata || {};
}
// 2. Source: App Webhook (data inside 'body')
else if (item.body && item.body.message && item.body.sessionId) {
  message = item.body.message;
  sessionId = item.body.sessionId;
  metadata = item.body.metadata || {};
}
// 3. Source: App Webhook (fallback - data at top level)
else if (item.message && item.sessionId) {
  message = item.message;
  sessionId = item.sessionId;
  metadata = item.metadata || {};
}

// Fallback sessionId to prevent crash
if (!sessionId) {
  sessionId = "unknown_user";
}

// Normalize metadata.user with readable field names
// Accept both new (metadata.user.*) and legacy flat fields for transition
const mdUser = (metadata.user && typeof metadata.user === 'object') ? metadata.user : {};
const user = {
  name: mdUser.name || metadata.userName || null,
  birthDate: mdUser.birthDate || metadata.dob || metadata.dateOfBirth || null,
  timeOfBirth: mdUser.timeOfBirth || metadata.tob || metadata.timeOfBirth || null,
  placeOfBirth: mdUser.placeOfBirth || metadata.pob || metadata.placeOfBirth || null,
  currentLocation: mdUser.currentLocation || metadata.currentLocation || null,
  age: mdUser.age ?? metadata.age ?? null,
  isAdult: (typeof mdUser.isAdult === 'boolean') ? mdUser.isAdult : ((typeof metadata.ageConfirmed === 'boolean') ? metadata.ageConfirmed : null),
  gender: mdUser.gender || null,
  locale: mdUser.locale || null,
  timezone: mdUser.timezone || null,
  location: mdUser.location || null,
  preferences: mdUser.preferences || null,
  id: mdUser.id || null,
  phoneNumber: mdUser.phoneNumber || null
};

// Build final metadata with structured user object
const finalMetadata = {
  user: user,
  session: metadata.session || { id: sessionId, startedAt: new Date().toISOString() },
  reqId: metadata.reqId || null,
  isSystemContext: !!metadata.isSystemContext,
  credits: metadata.credits ?? null,
  isPaid: !!metadata.isPaid,
  source: metadata.source || (item.contacts ? 'whatsapp' : 'app')
};

// Return message unchanged (no [USER INFO:...] prepending) with structured metadata
return [{ json: { message: message, sessionId: sessionId, source: (item.contacts ? "WHATSAPP" : "APP"), metadata: finalMetadata } }];

// Compute Age — Function node code (replace existing functionCode)
const now = new Date();
const metadata = (items[0] && items[0].json && items[0].json.metadata) ? items[0].json.metadata : {};
metadata.user = metadata.user || {};

const birthRaw = metadata.user.birthDate || metadata.user.dob || null;

function safeParseDate(s) {
  if (!s) return null;
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : d;
}

const birthDate = safeParseDate(birthRaw);

if (birthDate) {
  let age = now.getFullYear() - birthDate.getFullYear();
  const monthDiff = now.getMonth() - birthDate.getMonth();
  if (monthDiff < 0 || (monthDiff === 0 && now.getDate() < birthDate.getDate())) {
    age--;
  }
  const isAdult = age >= 18;

  metadata.user.age = age;
  metadata.user.isAdult = isAdult;
  metadata.user.ageComputedAt = now.toISOString();
  metadata.user.ageSource = birthRaw ? 'birthDate' : 'unknown';
} else {
  metadata.user.age = metadata.user.age != null ? metadata.user.age : null;
  metadata.user.isAdult = metadata.user.isAdult != null ? metadata.user.isAdult : null;
  metadata.user.ageComputedAt = now.toISOString();
  metadata.user.ageSource = 'no-birthDate';
}

items[0].json.metadata = metadata;
return items;

// Detect Clarification — looks for explicit agent flags or common clarification phrases in the AI output
const out = (items[0].json && (items[0].json.output || items[0].json.text || '')) ? (items[0].json.output || items[0].json.text) : '';
const meta = (items[0].json && items[0].json.metadata) ? items[0].json.metadata : {};

let needsClarification = false;
// 1) Prefer explicit structured signal from the AI if present
if (items[0].json && items[0].json.response && items[0].json.response.ai && items[0].json.response.ai.needsClarification === true) {
  needsClarification = true;
}
// 2) Heuristic fallback: common polite asks for DOB/place/time
if (!needsClarification) {
  const patterns = [ /\bcould you tell me\b/i, /\bplease tell me\b/i, /\bplease share\b/i, /\bwill you tell me\b/i, /\bcan you share\b/i, /\bprovide your\b/i, /\bdate of birth\b/i, /\bplace of birth\b/i, /\btime of birth\b/i, /\bcould you share your\b/i ];
  for (const p of patterns) {
    if (p.test(out)) { needsClarification = true; break; }
  }
}
items[0].json.needsClarification = needsClarification;
return items;

// Detect Clarification — prefer explicit agent signal, skip if structured profile is present
const out = (items[0].json && (items[0].json.output || items[0].json.text || '')) ? (items[0].json.output || items[0].json.text) : '';
const meta = (items[0].json && items[0].json.metadata) ? items[0].json.metadata : {};
const mdUser = meta.user || {};

let needsClarification = false;
// 1) Prefer explicit structured signal from the AI if present (honor this)
if (items[0].json && items[0].json.response && items[0].json.response.ai && items[0].json.response.ai.needsClarification === true) {
  needsClarification = true;
  items[0].json.needsClarification = true;
  return items;
}

// 2) If metadata indicates the user just supplied a profile, do NOT ask for DOB/place/time — skip clarification
if (meta.isProfileSynthesis === true || mdUser.birthDate || mdUser.timeOfBirth || mdUser.placeOfBirth) {
  items[0].json.needsClarification = false;
  return items;
}

// 3) Heuristic fallback: common polite asks for DOB/place/time — only used when no explicit signal and no supplied profile
const patterns = [ /\bcould you tell me\b/i, /\bplease tell me\b/i, /\bplease share\b/i, /\bwill you tell me\b/i, /\bcan you share\b/i, /\bprovide your\b/i, /\bdate of birth\b/i, /\bplace of birth\b/i, /\btime of birth\b/i, /\bcould you share your\b/i ];
for (const p of patterns) {
  if (p.test(out)) { needsClarification = true; break; }
}
items[0].json.needsClarification = needsClarification;
return items;
